from collections import deque


def _add_all_pairs(items, out):
    items = list(items)
    for i in range(len(items)):
        for j in range(i + 1, len(items)):
            a, b = items[i], items[j]
            if a == b:
                continue
            if a > b:
                a, b = b, a
            out.add((a, b))


def analyze_cfg(config, cfg):
    """Return live_in, live_out, interference, and call_forbidden.

    The least fixed point uses predecessor-edge phi inputs rather than ordinary
    successor uses.  Interference is the conservative undirected live-range
    graph and call_forbidden follows the live-after-call rule, excepting the
    call's own definition.
    """
    blocks = {b["id"]: b for b in cfg["blocks"]}
    block_ids = [b["id"] for b in cfg["blocks"]]

    phi_defs = {bid: set() for bid in block_ids}
    for bid, b in blocks.items():
        for phi in b["phis"]:
            phi_defs[bid].add(phi["def"])

    # Local upward-exposed uses and locally defined variables.
    use = {bid: set() for bid in block_ids}
    defined = {bid: set() for bid in block_ids}
    for bid in block_ids:
        b = blocks[bid]
        defined[bid].update(phi_defs[bid])
        seen = set(phi_defs[bid])
        for instr in b["instructions"]:
            for u in instr.get("uses", []):
                if u not in seen:
                    use[bid].add(u)
            d = instr.get("def")
            if d is not None:
                defined[bid].add(d)
                seen.add(d)

    # edge_use[pred][succ] is the set of variables read by successor phis on
    # that specific predecessor edge.
    edge_use = {bid: {} for bid in block_ids}
    for pred in block_ids:
        for succ in blocks[pred]["successors"]:
            vals = set()
            for phi in blocks[succ]["phis"]:
                vals.add(phi["inputs"][pred])
            edge_use[pred][succ] = vals

    live_in = {bid: set() for bid in block_ids}
    live_out = {bid: set() for bid in block_ids}

    # Chaotic iteration from the bottom value reaches the least fixed point
    # because every equation is monotone.
    changed = True
    while changed:
        changed = False
        for bid in block_ids:
            b = blocks[bid]

            old_in = live_in[bid]
            new_in = set(use[bid])
            new_in.update(live_out[bid] - defined[bid])
            if new_in != old_in:
                live_in[bid] = new_in
                changed = True

            old_out = live_out[bid]
            new_out = set()
            for succ in b["successors"]:
                new_out.update(live_in[succ] - phi_defs[succ])
                new_out.update(edge_use[bid][succ])
            if new_out != old_out:
                live_out[bid] = new_out
                changed = True

    interference = set()
    call_forbidden = {}

    clobbered = list(config.get("call_clobbered", []))

    for bid in block_ids:
        b = blocks[bid]
        live = set(live_out[bid])
        _add_all_pairs(live, interference)

        for instr in reversed(b["instructions"]):
            live_after = set(live)
            d = instr.get("def")

            if instr.get("call"):
                for v in live_after:
                    if v == d:
                        continue
                    forbid = call_forbidden.setdefault(v, set())
                    forbid.update(clobbered)

            if d is not None:
                for v in live_after:
                    if v != d:
                        a, bb = (d, v) if d <= v else (v, d)
                        if a != bb:
                            interference.add((a, bb))
                live.discard(d)

            for u in instr.get("uses", []):
                live.add(u)
            _add_all_pairs(live, interference)

        _add_all_pairs(live, interference)
        _add_all_pairs(live_in[bid], interference)

    # Public formats use lists rather than sets.  Deterministic ordering is
    # harmless because the comparison layer normalizes unordered collections.
    live_in_list = {bid: sorted(live_in[bid]) for bid in block_ids}
    live_out_list = {bid: sorted(live_out[bid]) for bid in block_ids}
    interference_list = [[a, b] for a, b in sorted(interference)]
    call_forbidden_list = {
        v: sorted(regs) for v, regs in call_forbidden.items() if regs
    }

    return {
        "live_in": live_in_list,
        "live_out": live_out_list,
        "interference": interference_list,
        "call_forbidden": call_forbidden_list,
    }

def allocate(config, cfg, spill_cost, edge_frequency, facts):
    """Return the allocation portion of the SPEC report.

    Primary objective is the exact minimum total spill cost.  Among all
    allocations attaining that minimum, the secondary objective is the exact
    minimum frequency-weighted phi-copy cost.  The search is exhaustive with
    branch-and-bound and memoized graph-colouring/obstruction checks, so it is
    not relying on any greedy degree/ID ordering.
    """

    def bits(mask):
        while mask:
            lsb = mask & -mask
            yield lsb.bit_length() - 1
            mask ^= lsb

    blocks = {b["id"]: b for b in cfg["blocks"]}
    registers = config["registers"]
    k = len(registers)
    reg_index = {r: i for i, r in enumerate(registers)}
    all_colors_mask = (1 << k) - 1 if k else 0

    variables = list(spill_cost.keys())
    n = len(variables)
    idx = {v: i for i, v in enumerate(variables)}
    all_mask = (1 << n) - 1

    precolor_assign = [-1] * n
    for v, r in config.get("precolors", {}).items():
        precolor_assign[idx[v]] = reg_index[r]
    precolored_mask = 0
    for i, c in enumerate(precolor_assign):
        if c != -1:
            precolored_mask |= 1 << i
    spillable_mask = all_mask & ~precolored_mask

    forbidden_bits = [0] * n
    for v, regs in facts.get("call_forbidden", {}).items():
        for r in regs:
            forbidden_bits[idx[v]] |= 1 << reg_index[r]

    adj = [0] * n
    interference_edges = list(facts.get("interference", []))
    for u, v in interference_edges:
        i, j = idx[u], idx[v]
        adj[i] |= 1 << j
        adj[j] |= 1 << i

    # Error precedence from the specification.
    for v, r in config.get("precolors", {}).items():
        i = idx[v]
        ri = reg_index[r]
        if forbidden_bits[i] & (1 << ri):
            return {
                "status": "UNSAT_PRECOLOR",
                "reason": "PRECOLOR_CALL_CLOBBER",
                "min_spill": None,
                "copy_cost": None,
                "locations": {},
                "spills": [],
                "edge_moves": [],
            }

    for u, v in interference_edges:
        i, j = idx[u], idx[v]
        if precolor_assign[i] != -1 and precolor_assign[j] != -1:
            if precolor_assign[i] == precolor_assign[j]:
                return {
                    "status": "UNSAT_PRECOLOR",
                    "reason": "PRECOLOR_INTERFERENCE",
                    "min_spill": None,
                    "copy_cost": None,
                    "locations": {},
                    "spills": [],
                    "edge_moves": [],
                }

    # Memoized exact graph-colouring routine.  ``mask`` must include every
    # precoloured variable, because pinned variables may not be spilled.
    colour_cache = {}

    def find_colouring(mask):
        if mask in colour_cache:
            return colour_cache[mask]

        for i, c in enumerate(precolor_assign):
            if c != -1 and not ((mask >> i) & 1):
                colour_cache[mask] = None
                return None

        colours = [-1] * n
        for i, c in enumerate(precolor_assign):
            if c != -1:
                colours[i] = c

        kept_neighbors = [adj[i] & mask for i in range(n)]
        remaining = [i for i in range(n) if ((mask >> i) & 1) and colours[i] == -1]

        def rec():
            if not remaining:
                return True

            best_v = -1
            best_avail = 0
            best_cnt = 10 ** 9
            for v in remaining:
                avail = all_colors_mask & ~forbidden_bits[v]
                nb = kept_neighbors[v]
                while nb:
                    u = (nb & -nb).bit_length() - 1
                    if colours[u] != -1:
                        avail &= ~(1 << colours[u])
                    nb &= nb - 1
                cnt = avail.bit_count()
                if cnt == 0:
                    return False
                if cnt < best_cnt:
                    best_cnt = cnt
                    best_v = v
                    best_avail = avail

            remaining.remove(best_v)
            for c in bits(best_avail):
                colours[best_v] = c
                if rec():
                    return True
                colours[best_v] = -1
            remaining.append(best_v)
            return False

        result = tuple(colours) if rec() else None
        colour_cache[mask] = result
        return result

    obstruction_cache = {}

    def minimal_obstruction(mask):
        """A minimal uncolourable subset of ``mask``.

        Precoloured vertices are never removed because they cannot be spilled.
        """
        if mask in obstruction_cache:
            return obstruction_cache[mask]

        cset = mask
        while True:
            removed = False
            for v in bits(cset):
                if precolor_assign[v] != -1:
                    continue
                cand = cset & ~(1 << v)
                if find_colouring(cand) is None:
                    cset = cand
                    removed = True
                    break
            if not removed:
                break

        obstruction_cache[mask] = cset
        return cset

    def spill_cost_of(mask):
        total = 0
        for v in bits(mask):
            total += spill_cost[variables[v]]
        return total

    # Greedy legal spill set gives a valid upper bound for the primary search.
    greedy_spill = 0
    kept = all_mask
    while find_colouring(kept) is None:
        cset = minimal_obstruction(kept)
        cands = [v for v in bits(cset) if (spillable_mask >> v) & 1]
        if not cands:
            # The precolour checks cover the only specified UNSAT reasons;
            # this is defensive only.
            return {
                "status": "UNSAT_PRECOLOR",
                "reason": "PRECOLOR_INTERFERENCE",
                "min_spill": None,
                "copy_cost": None,
                "locations": {},
                "spills": [],
                "edge_moves": [],
            }
        v = min(cands, key=lambda x: (spill_cost[variables[x]], x))
        greedy_spill |= 1 << v
        kept &= ~(1 << v)

    best_spill = greedy_spill
    best_spill_cost = spill_cost_of(greedy_spill)
    primary_visited = set()

    def primary_dfs(spill_mask):
        nonlocal best_spill, best_spill_cost
        if spill_mask in primary_visited:
            return
        primary_visited.add(spill_mask)

        cost = spill_cost_of(spill_mask)
        if cost >= best_spill_cost:
            return

        kept_mask = all_mask & ~spill_mask
        if find_colouring(kept_mask) is not None:
            best_spill = spill_mask
            best_spill_cost = cost
            return

        cset = minimal_obstruction(kept_mask)
        cands = [v for v in bits(cset) if (spillable_mask >> v) & 1]
        if not cands:
            return
        if cost + min(spill_cost[variables[v]] for v in cands) >= best_spill_cost:
            return
        for v in sorted(cands, key=lambda x: (spill_cost[variables[x]], x)):
            primary_dfs(spill_mask | (1 << v))

    primary_dfs(0)
    min_spill = best_spill_cost

    # Build the weighted phi-copy relation used by the secondary objective.
    freq = {(e["pred"], e["succ"]): e["frequency"] for e in edge_frequency}
    phi_edges = []
    for b in cfg["blocks"]:
        pred = b["id"]
        for succ in b["successors"]:
            f = freq[(pred, succ)]
            for phi in blocks[succ]["phis"]:
                src = phi["inputs"][pred]
                dst = phi["def"]
                phi_edges.append((idx[src], idx[dst], f))

    copy_cache = {}

    def min_copy_for_kept(kept_mask):
        if kept_mask in copy_cache:
            return copy_cache[kept_mask]

        base_colours = find_colouring(kept_mask)
        if base_colours is None:
            copy_cache[kept_mask] = None
            return None

        wmat = [[0] * n for _ in range(n)]
        for a, b, w in phi_edges:
            if ((kept_mask >> a) & 1) and ((kept_mask >> b) & 1):
                wmat[a][b] += w
                wmat[b][a] += w

        # Components of the combined interference + weighted-copy graph are
        # independent for both legality and cost.
        comp = [-1] * n
        comps = []
        for start in bits(kept_mask):
            if comp[start] != -1:
                continue
            cid = len(comps)
            stack = [start]
            comp[start] = cid
            cur = []
            while stack:
                x = stack.pop()
                cur.append(x)
                # Neighbours through interference or any phi copy.
                nb = adj[x] & kept_mask
                for y in bits(nb):
                    if comp[y] == -1:
                        comp[y] = cid
                        stack.append(y)
                for y in range(n):
                    if ((kept_mask >> y) & 1) and wmat[x][y] and comp[y] == -1:
                        comp[y] = cid
                        stack.append(y)
            comps.append(cur)

        def optimize_component(vs):
            m = len(vs)
            if m == 0:
                return 0, []

            inter_local = [0] * m
            for p, gp in enumerate(vs):
                for q, gq in enumerate(vs):
                    if p != q and ((adj[gp] >> gq) & 1):
                        inter_local[p] |= 1 << q

            allowed = [all_colors_mask & ~forbidden_bits[gp] for gp in vs]
            wloc = [[0] * m for _ in range(m)]
            has_weight = False
            for p, gp in enumerate(vs):
                for q, gq in enumerate(vs):
                    if p < q and wmat[gp][gq]:
                        wloc[p][q] = wmat[gp][gq]
                        wloc[q][p] = wmat[gp][gq]
                        has_weight = True

            initial = [base_colours[gp] for gp in vs]
            for p, gp in enumerate(vs):
                if precolor_assign[gp] != -1:
                    initial[p] = precolor_assign[gp]

            def cost_of(cols):
                total = 0
                for p in range(m):
                    for q in range(p + 1, m):
                        if wloc[p][q] and cols[p] != cols[q]:
                            total += wloc[p][q]
                return total

            if not has_weight:
                return 0, initial

            fixed = {
                p: precolor_assign[gp]
                for p, gp in enumerate(vs)
                if precolor_assign[gp] != -1
            }
            canonical = not fixed and all(a == all_colors_mask for a in allowed)

            colours = [-1] * m
            for p, c in fixed.items():
                colours[p] = c

            best_cost = cost_of(initial)
            best_colours = initial[:]

            def rec(partial):
                nonlocal best_cost, best_colours
                unassigned = [p for p in range(m) if colours[p] == -1]
                if not unassigned:
                    if partial < best_cost:
                        best_cost = partial
                        best_colours = colours[:]
                    return

                assigned = [q for q in range(m) if colours[q] != -1]

                # Admissible lower bound: each unassigned vertex pays at least
                # its cheapest disagreement cost against assigned vertices.
                lb = partial
                avail_map = {}
                chosen_p = -1
                chosen_avail = 0
                chosen_cnt = 10 ** 9
                chosen_min = -1

                for p in unassigned:
                    avail = allowed[p]
                    for q in assigned:
                        if (inter_local[p] >> q) & 1:
                            avail &= ~(1 << colours[q])
                    if avail == 0:
                        return
                    avail_map[p] = avail
                    best_m = 10 ** 30
                    for c in bits(avail):
                        m = 0
                        for q in assigned:
                            if wloc[p][q] and colours[q] != c:
                                m += wloc[p][q]
                        if m < best_m:
                            best_m = m
                    lb += best_m
                    cnt = avail.bit_count()
                    if cnt < chosen_cnt or (cnt == chosen_cnt and best_m > chosen_min):
                        chosen_cnt = cnt
                        chosen_p = p
                        chosen_avail = avail
                        chosen_min = best_m

                if lb >= best_cost:
                    return

                margins = []
                for c in bits(chosen_avail):
                    m = 0
                    for q in assigned:
                        if wloc[chosen_p][q] and colours[q] != c:
                            m += wloc[chosen_p][q]
                    margins.append((m, c))
                margins.sort()

                if canonical:
                    max_used = max([colours[q] for q in assigned], default=-1)
                    limit = min(k - 1, max_used + 1)
                    margins = [(m, c) for m, c in margins if c <= limit]
                    if not margins:
                        return

                for m, c in margins:
                    colours[chosen_p] = c
                    rec(partial + m)
                    colours[chosen_p] = -1

            rec(cost_of(initial))
            return best_cost, best_colours

        full_colours = [-1] * n
        total_cost = 0
        for vs in comps:
            has_weight = any(
                wmat[vs[p]][vs[q]] for p in range(len(vs)) for q in range(p + 1, len(vs))
            )
            if has_weight:
                cost, cols = optimize_component(vs)
                total_cost += cost
                for gp, c in zip(vs, cols):
                    full_colours[gp] = c
            else:
                for gp in vs:
                    full_colours[gp] = base_colours[gp]

        for i, c in enumerate(precolor_assign):
            if c != -1 and ((kept_mask >> i) & 1):
                full_colours[i] = c

        result = (total_cost, tuple(full_colours))
        copy_cache[kept_mask] = result
        return result

    # Enumerate every minimum-spill subset and evaluate its optimal colouring.
    optimal_masks = []
    enum_visited = set()

    def enum_masks(spill_mask):
        if spill_mask in enum_visited:
            return
        enum_visited.add(spill_mask)

        cost = spill_cost_of(spill_mask)
        if cost > min_spill:
            return
        kept_mask = all_mask & ~spill_mask
        if cost == min_spill:
            if find_colouring(kept_mask) is not None:
                optimal_masks.append(spill_mask)
            return

        # cost < min_spill; if this were already colourable it would contradict
        # the primary optimum, but keep the check for safety.
        if find_colouring(kept_mask) is not None:
            return

        cset = minimal_obstruction(kept_mask)
        cands = [v for v in bits(cset) if (spillable_mask >> v) & 1]
        for v in sorted(cands, key=lambda x: (spill_cost[variables[x]], x)):
            enum_masks(spill_mask | (1 << v))

    enum_masks(0)

    best_total_copy = None
    best_spill = None
    best_full_colours = None

    for spill_mask in optimal_masks:
        kept_mask = all_mask & ~spill_mask
        solved = min_copy_for_kept(kept_mask)
        if solved is None:
            continue
        var_cost, full_colours = solved
        total_copy = var_cost
        for a, b, w in phi_edges:
            if not (((kept_mask >> a) & 1) and ((kept_mask >> b) & 1)):
                total_copy += w
        if best_total_copy is None or total_copy < best_total_copy:
            best_total_copy = total_copy
            best_spill = spill_mask
            best_full_colours = full_colours

    if best_spill is None:
        # Defensive fallback; the primary search normally always finds a legal
        # allocation for well-formed input.
        return {
            "status": "UNSAT_PRECOLOR",
            "reason": "PRECOLOR_INTERFERENCE",
            "min_spill": None,
            "copy_cost": None,
            "locations": {},
            "spills": [],
            "edge_moves": [],
        }

    locations = {}
    for i, v in enumerate(variables):
        if (best_spill >> i) & 1:
            locations[v] = "spill:" + v
        elif precolor_assign[i] != -1:
