    minimum frequency-weighted phi-copy cost.  The search is exhaustive with
    branch-and-bound and memoized graph-colouring/obstruction checks, so it is
    not relying on any greedy degree/ID ordering.
    """

    def bits(mask):
        while mask:
            lsb = mask & -mask
            yield lsb.bit_length() - 1
            mask ^= lsb

    blocks = {b["id"]: b for b in cfg["blocks"]}
    registers = config["registers"]
    k = len(registers)
    reg_index = {r: i for i, r in enumerate(registers)}
    all_colors_mask = (1 << k) - 1 if k else 0

    variables = list(spill_cost.keys())
    n = len(variables)
    idx = {v: i for i, v in enumerate(variables)}
    all_mask = (1 << n) - 1

    precolor_assign = [-1] * n
    for v, r in config.get("precolors", {}).items():
        precolor_assign[idx[v]] = reg_index[r]
    precolored_mask = 0
    for i, c in enumerate(precolor_assign):
        if c != -1:
            precolored_mask |= 1 << i
    spillable_mask = all_mask & ~precolored_mask

    forbidden_bits = [0] * n
    for v, regs in facts.get("call_forbidden", {}).items():
        for r in regs:
            forbidden_bits[idx[v]] |= 1 << reg_index[r]

    adj = [0] * n
    interference_edges = list(facts.get("interference", []))
    for u, v in interference_edges:
        i, j = idx[u], idx[v]
        adj[i] |= 1 << j
        adj[j] |= 1 << i

    # Error precedence from the specification.
    for v, r in config.get("precolors", {}).items():
        i = idx[v]
        ri = reg_index[r]
