                for q, gq in enumerate(vs):
                    if p < q and wmat[gp][gq]:
                        wloc[p][q] = wmat[gp][gq]
                        wloc[q][p] = wmat[gp][gq]
                        has_weight = True

            initial = [base_colours[gp] for gp in vs]
            for p, gp in enumerate(vs):
                if precolor_assign[gp] != -1:
                    initial[p] = precolor_assign[gp]

            def cost_of(cols):
                total = 0
                for p in range(m):
                    for q in range(p + 1, m):
                        if wloc[p][q] and cols[p] != cols[q]:
                            total += wloc[p][q]
                return total

