            "min_spill": None,
            "copy_cost": None,
            "locations": {},
            "spills": [],
            "edge_moves": [],
        }

    locations = {}
    for i, v in enumerate(variables):
        if (best_spill >> i) & 1:
            locations[v] = "spill:" + v
        elif precolor_assign[i] != -1:
            locations[v] = "reg:" + registers[precolor_assign[i]]
