    edge_moves = []
    total_copy_check = 0
    for b in cfg["blocks"]:
        pred = b["id"]
        for succ in b["successors"]:
            f = freq[(pred, succ)]
            moves = []
            graph = {}
            for phi in blocks[succ]["phis"]:
                src = phi["inputs"][pred]
                dst = phi["def"]
                from_loc = locations[src]
                to_loc = locations[dst]
                if from_loc != to_loc:
