                for v in graph.get(u, ()):
                    if v not in state:
                        if has_cycle(v):
                            return True
                    elif state[v] == GRAY:
                        return True
                state[u] = BLACK
                return False

            cycle = False
            for u in graph:
                if u not in state:
                    if has_cycle(u):
                        cycle = True
                        break

            edge_moves.append({
                "pred": pred,
                "succ": succ,
                "moves": moves,
                "cycle": cycle,
            })

    return {
        "status": "ALLOCATED",
        "reason": None,
        "min_spill": min_spill,
