import unittest

VISIBLE_DOCUMENT = "engines/analysis/SPEC.md"
TARGET = "engines/analysis/engine.py"

API_BOUNDARY_REQUIREMENTS = [
    {
        "target_path": TARGET,
        "function": "transform",
        "rules": {
            "nonfinite_unknown_field": {
                "applicable": False,
                "contract_path": VISIBLE_DOCUMENT,
                "requirement_quote": (
                    "Input contains config,cfg,spill_cost,edge_frequency. "
                    "edge_frequency has exactly one {pred,succ,frequency} row "
                    "per CFG edge, with integer frequency1-100"
                ),
                "reason": (
                    "SPEC defines the request shape and well-formed domain data, "
                    "but does not state a ValueError contract for unknown or "
                    "non-finite input fields."
                ),
            },
            "invalid_payload_type": {
                "applicable": False,
                "contract_path": VISIBLE_DOCUMENT,
                "requirement_quote": (
                    "Input contains config,cfg,spill_cost,edge_frequency. "
                    "edge_frequency has exactly one {pred,succ,frequency} row "
                    "per CFG edge, with integer frequency1-100"
                ),
                "reason": (
                    "SPEC describes the fields of the request object but leaves "
                    "top-level payload type validation unspecified; no visible "
                    "rule requires transform to raise ValueError."
                ),
            },
        },
    }
]


def _public_request():
    return {
        "config": {
            "registers": ["R0", "R1"],
            "call_clobbered": [],
            "precolors": {"a": "R0", "b": "R1"},
        },
        "cfg": {
            "entry": "E",
            "parameters": ["a", "b"],
            "blocks": [
                {"id": "E", "successors": ["P", "Q"], "phis": [], "instructions": []},
                {"id": "P", "successors": ["M"], "phis": [], "instructions": []},
                {"id": "Q", "successors": ["M"], "phis": [], "instructions": []},
                {
                    "id": "M",
                    "successors": [],
                    "phis": [
                        {"def": "x", "inputs": {"P": "a", "Q": "b"}},
                        {"def": "y", "inputs": {"P": "b", "Q": "a"}},
                    ],
                    "instructions": [
                        {"id": "use", "uses": ["x", "y"], "def": None, "call": False}
                    ],
                },
            ],
        },
        "spill_cost": {"a": 1, "b": 1, "x": 1, "y": 1},
        "edge_frequency": [
            {"pred": "E", "succ": "P", "frequency": 1},
            {"pred": "E", "succ": "Q", "frequency": 1},
            {"pred": "P", "succ": "M", "frequency": 1},
            {"pred": "Q", "succ": "M", "frequency": 3},
        ],
    }


class DataflowAndAllocationTests(unittest.TestCase):
    def test_call_clobber_precolor_precedence(self):
        # SPEC: PRECOLOR_CALL_CLOBBER takes precedence over an interfering
        # pinned pair.  Here a is pinned to R0 and live after a call that
        # clobbers R0, so the result must be UNSAT_PRECOLOR.
        request = {
            "config": {
                "registers": ["R0"],
                "call_clobbered": ["R0"],
                "precolors": {"a": "R0"},
            },
            "cfg": {
                "entry": "P",
                "parameters": ["a"],
                "blocks": [
                    {
                        "id": "P",
                        "successors": ["Q"],
                        "phis": [],
                        "instructions": [
                            {"id": "call", "uses": [], "def": "c", "call": True}
                        ],
                    },
                    {
                        "id": "Q",
                        "successors": [],
                        "phis": [{"def": "x", "inputs": {"P": "a"}}],
                        "instructions": [
                            {"id": "use", "uses": ["x", "c"], "def": None, "call": False}
                        ],
                    },
                ],
            },
            "spill_cost": {"a": 1, "c": 1, "x": 1},
            "edge_frequency": [{"pred": "P", "succ": "Q", "frequency": 1}],
        }
        result = call_candidate(TARGET, "transform", args=[{"request": request}, {}])
        self.assertEqual(result["status"], "UNSAT_PRECOLOR")
        self.assertEqual(result["reason"], "PRECOLOR_CALL_CLOBBER")
        self.assertIsNone(result["min_spill"])
        self.assertIsNone(result["copy_cost"])
        self.assertEqual(result["locations"], {})
        self.assertEqual(result["spills"], [])
        self.assertEqual(result["edge_moves"], [])

    def test_reversed_frequencies_pick_cold_edge(self):
        # SPEC: equal spill costs are allowed, but copy cost is frequency
        # weighted.  Swapping the two phi-edge frequencies must swap the chosen
        # x/y registers while keeping copy_cost at 2.
        request = _public_request()
        request["edge_frequency"] = [
            {"pred": "E", "succ": "P", "frequency": 1},
            {"pred": "E", "succ": "Q", "frequency": 1},
            {"pred": "P", "succ": "M", "frequency": 3},
            {"pred": "Q", "succ": "M", "frequency": 1},
        ]
        result = call_candidate(TARGET, "transform", args=[{"request": request}, {}])
        self.assertEqual(result["status"], "ALLOCATED")
        self.assertEqual(result["min_spill"], 0)
        self.assertEqual(result["copy_cost"], 2)
        self.assertEqual(result["locations"]["a"], "reg:R0")
        self.assertEqual(result["locations"]["b"], "reg:R1")
        self.assertEqual(result["locations"]["x"], "reg:R0")
        self.assertEqual(result["locations"]["y"], "reg:R1")
        self.assertEqual(result["spills"], [])
        # The hot edge P->M has no moves; the cold Q->M edge is a parallel cycle.
        by_edge = {(row["pred"], row["succ"]): row for row in result["edge_moves"]}
        self.assertEqual(by_edge[("P", "M")]["moves"], [])
        self.assertEqual(len(by_edge[("Q", "M")]["moves"]), 2)
        self.assertTrue(by_edge[("Q", "M")]["cycle"])

    def test_dataflow_call_liveness_and_interference(self):
        # SPEC helper contract: P has parameter a and a call defining c.  Its
        # successor Q defines phi x from the P->Q edge and uses x and c.
        request = {
            "config": {
                "registers": ["R0"],
                "call_clobbered": ["R0"],
                "precolors": {},
            },
            "cfg": {
                "entry": "P",
                "parameters": ["a"],
                "blocks": [
                    {
                        "id": "P",
                        "successors": ["Q"],
                        "phis": [],
                        "instructions": [
                            {"id": "call", "uses": [], "def": "c", "call": True}
                        ],
                    },
                    {
                        "id": "Q",
                        "successors": [],
                        "phis": [{"def": "x", "inputs": {"P": "a"}}],
                        "instructions": [
                            {"id": "use", "uses": ["x", "c"], "def": None, "call": False}
                        ],
                    },
                ],
            },
            "spill_cost": {"a": 1, "c": 1, "x": 1},
            "edge_frequency": [{"pred": "P", "succ": "Q", "frequency": 1}],
        }
        result = call_candidate(TARGET, "transform", args=[{"request": request}, {}])
        self.assertEqual(set(result["live_out"]["P"]), {"a", "c"})
        self.assertEqual(set(result["live_in"]["Q"]), {"c"})
        self.assertEqual(
            {tuple(sorted(e)) for e in result["interference"]},
            {("a", "c"), ("c", "x")},
        )
        self.assertEqual(result["call_forbidden"], {"a": ["R0"]})


if __name__ == "__main__":
    unittest.main()
